import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const options = [
  { id: 'reading', label: 'Reading' },
  { id: 'finished', label: 'Finished' },
  { id: 'want-to-read', label: 'Want to read' },
];

describe('ChipBar', () => {
  it('renders a chip for each option', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Finished' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Want to read' })).toBeInTheDocument();
  });

  it('unselected chip has aria-pressed="false"', () => {
    render(<ChipBar options={options} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('selected chip has aria-pressed="true"', () => {
    render(<ChipBar options={options} selected={['reading']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'true');
  });

  it('non-selected chips remain aria-pressed="false" when others are selected', () => {
    render(<ChipBar options={options} selected={['reading']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Finished' })).toHaveAttribute('aria-pressed', 'false');
    expect(screen.getByRole('button', { name: 'Want to read' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('clicking an unselected chip calls onSelectionChange with it added', async () => {
    const handleChange = vi.fn();
    render(<ChipBar options={options} selected={['reading']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Finished' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(expect.arrayContaining(['reading', 'finished']));
  });

  it('clicking a selected chip calls onSelectionChange with it removed', async () => {
    const handleChange = vi.fn();
    render(<ChipBar options={options} selected={['reading', 'finished']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledOnce();
    const [nextSelected] = handleChange.mock.calls[0];
    expect(nextSelected).not.toContain('reading');
    expect(nextSelected).toContain('finished');
  });

  it('multiple chips can be selected simultaneously', () => {
    render(<ChipBar options={options} selected={['reading', 'finished']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Finished' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Want to read' })).toHaveAttribute('aria-pressed', 'false');
  });

  it('deselecting the last selected chip results in empty selection', async () => {
    const handleChange = vi.fn();
    render(<ChipBar options={options} selected={['reading']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    expect(handleChange).toHaveBeenCalledWith([]);
  });
});

