import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import type { Book } from '../types';
import * as api from '../api';
import { useBooks } from './useBooks';

afterEach(() => {
  vi.restoreAllMocks();
});

describe('useBooks', () => {
  it('starts in loading state with no data or error', () => {
    // Never-resolving promise lets us observe the in-flight state
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {}));
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions to loaded state with books when getBooks resolves', async () => {
    const books: Book[] = [
      { id: '1', title: 'Dune', author: 'Frank Herbert', status: 'reading' },
    ];
    vi.spyOn(api, 'getBooks').mockResolvedValue(books);
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.data).toEqual(books);
    expect(result.current.error).toBeNull();
  });

  it('transitions to error state when getBooks rejects', async () => {
    const err = new Error('load failed');
    vi.spyOn(api, 'getBooks').mockRejectedValue(err);
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.loading).toBe(false);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBe(err);
  });

  it('wraps non-Error rejections in an Error object', async () => {
    vi.spyOn(api, 'getBooks').mockRejectedValue('network down');
    const { result } = renderHook(() => useBooks());
    await act(async () => {});
    expect(result.current.error).toBeInstanceOf(Error);
    expect(result.current.error?.message).toBe('network down');
  });
});

